import { Controller } from "@hotwired/stimulus"
import { differenceInDays, secondsToDate } from "helpers/date_helpers"

const DEFAULT_LOCALE = "en-US"

export default class extends Controller {
  static targets = [ "time", "date", "datetime", "shortdate", "ago", "indays", "daysago", "agoorweekday", "timeordate" ]
  static values = { refreshInterval: Number }
  static classes = [ "local-time-value"]

  #timer

  initialize() {
    this.locale = document.documentElement.lang === "ja" ? "ja-JP" : DEFAULT_LOCALE
    this.japanese = this.locale.startsWith("ja")
    this.timeFormatter = new Intl.DateTimeFormat(this.locale, { timeStyle: "short" })
    this.dateFormatter = new Intl.DateTimeFormat(this.locale, { dateStyle: "long" })
    this.shortdateFormatter = new Intl.DateTimeFormat(this.locale, { month: "short", day: "numeric" })
    this.datetimeFormatter = new Intl.DateTimeFormat(this.locale, { timeStyle: "short", dateStyle: "short" })
    this.agoFormatter = new AgoFormatter(this.locale)
    this.daysagoFormatter = new DaysAgoFormatter(this.japanese)
    this.datewithweekdayFormatter = new Intl.DateTimeFormat(this.locale, { weekday: "long", month: "long", day: "numeric" })
    this.indaysFormatter = new InDaysFormatter(this.japanese)
    this.agoorweekdayFormatter = new DaysAgoOrWeekdayFormatter(this.locale, this.japanese)
    this.timeordateFormatter = new TimeOrDateFormatter(this.locale)
  }

  connect() {
    this.#timer = setInterval(() => this.#refreshRelativeTimes(), 30_000)
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  refreshAll() {
    this.constructor.targets.forEach(targetName => {
      this.targets.findAll(targetName).forEach(target => {
        this.#formatTime(this[`${targetName}Formatter`], target)
      })
    })
  }

  refreshTarget(event) {
    const target = event.target
    const targetName = target.dataset.localTimeTarget
    this.#formatTime(this[`${targetName}Formatter`], target)
  }

  timeTargetConnected(target) {
    this.#formatTime(this.timeFormatter, target)
  }

  dateTargetConnected(target) {
    this.#formatTime(this.dateFormatter, target)
  }

  datetimeTargetConnected(target) {
    this.#formatTime(this.datetimeFormatter, target)
  }

  shortdateTargetConnected(target) {
    this.#formatTime(this.shortdateFormatter, target)
  }

  agoTargetConnected(target) {
    this.#formatTime(this.agoFormatter, target)
  }

  indaysTargetConnected(target) {
    this.#formatTime(this.indaysFormatter, target)
  }

  daysagoTargetConnected(target) {
    this.#formatTime(this.daysagoFormatter, target)
  }

  agoorweekdayTargetConnected(target) {
    this.#formatTime(this.agoorweekdayFormatter, target)
  }

  timeordateTargetConnected(target) {
    this.#formatTime(this.timeordateFormatter, target)
  }

  #refreshRelativeTimes() {
    this.agoTargets.forEach(target => {
      this.#formatTime(this.agoFormatter, target)
    })
  }

  #formatTime(formatter, target) {
    const dt = secondsToDate(parseInt(target.getAttribute("datetime")))
    target.innerHTML = formatter.format(dt)
    target.title = this.datetimeFormatter.format(dt)
  }
}

class AgoFormatter {
  constructor(locale) {
    this.locale = locale
    this.japanese = locale.startsWith("ja")
    this.relativeTimeFormatter = new Intl.RelativeTimeFormat(locale, { numeric: "always" })
  }

  format(dt) {
    const now = new Date()
    const seconds = (now - dt) / 1000
    const minutes = seconds / 60
    const hours = minutes / 60
    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (years >= 1) return this.#format("year", years)
    if (months >= 1) return this.#format("month", months)
    if (weeks >= 1) return this.#format("week", weeks)
    if (days >= 1) return this.#format("day", days)
    if (hours >= 1) return this.#format("hour", hours)
    if (minutes >= 1) return this.#format("minute", minutes)

    return this.japanese ? "1分未満前" : "Less than a minute ago"
  }

  #format(unit, quantity) {
    quantity = Math.floor(quantity)

    if (this.japanese) {
      return this.relativeTimeFormatter.format(-quantity, unit)
    }

    const suffix = (quantity === 1) ? "" : "s"
    return `${quantity} ${unit}${suffix} ago`
  }
}

class DaysAgoFormatter {
  constructor(japanese) {
    this.japanese = japanese
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 0) return styleableValue(this.japanese ? "今日" : "today")
    if (days === 1) return styleableValue(this.japanese ? "昨日" : "yesterday")
    return this.japanese ? `${styleableValue(days)}日前` : `${styleableValue(days)} days ago`
  }
}

class DaysAgoOrWeekdayFormatter {
  constructor(locale, japanese) {
    this.locale = locale
    this.japanese = japanese
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 1) {
      return new DaysAgoFormatter(this.japanese).format(date)
    } else {
      return new Intl.DateTimeFormat(this.locale, { weekday: "long", month: "long", day: "numeric" }).format(date)
    }
  }
}

class InDaysFormatter {
  constructor(japanese) {
    this.japanese = japanese
  }

  format(date) {
    const days = differenceInDays(new Date(), date)

    if (days <= 0) return styleableValue(this.japanese ? "今日" : "today")
    if (days === 1) return styleableValue(this.japanese ? "明日" : "tomorrow")
    return this.japanese ? `${styleableValue(days)}日後` : `in ${styleableValue(days)} days`
  }
}

class TimeOrDateFormatter {
  constructor(locale) {
    this.locale = locale
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days >= 1) {
      return new Intl.DateTimeFormat(this.locale, { month: "short", day: "numeric" }).format(date)
    } else {
      return new Intl.DateTimeFormat(this.locale, { timeStyle: "short" }).format(date)
    }
  }
}

function styleableValue(value) {
  return `<span class="local-time-value">${value}</span>`
}
