  get #day() { return document.documentElement.lang === "ja" ? "日" : "day" }
  get #days() { return document.documentElement.lang === "ja" ? "日" : "days" }

  #hide() {
    this.element.toggleAttribute("hidden", true)
  }

  #show() {
    this.element.removeAttribute("hidden")
  }
